const raw = $input.first().json || {};
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const email = String(body.email || '').trim();
if (!email) {
  throw new Error('Application status webhook is missing email. Laravel must POST JSON with an email field.');
}
const message = body.message || '';
if (!message) {
  throw new Error('Application status webhook is missing message HTML.');
}
return [{
  json: {
    email,
    subject: body.subject || 'Your TechHRM application update',
    message,
    from_name: body.from_name || 'TechHRM WSPO',
  },
}];
